package dev.joaomendonca.agendapro.service.api;import dev.joaomendonca.agendapro.service.application.ServiceOfferingService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.net.URI;import java.util.*;
@RestController @RequestMapping("/api/v1/services") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class ServiceController{private final ServiceOfferingService service;public ServiceController(ServiceOfferingService service){this.service=service;}@PostMapping public ResponseEntity<ServiceResponse> create(@Valid @RequestBody ServiceRequest r){var s=service.create(r);return ResponseEntity.created(URI.create("/api/v1/services/"+s.id())).body(s);}@GetMapping public List<ServiceResponse> list(){return service.list();}@GetMapping("/{id}") public ServiceResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public ServiceResponse update(@PathVariable UUID id,@Valid @RequestBody ServiceRequest r){return service.update(id,r);}@PatchMapping("/{id}/status") public ServiceResponse status(@PathVariable UUID id,@Valid @RequestBody ServiceStatusRequest r){return service.status(id,r);}}
